 "content": "def transform(grid):
    # Clear complete solid 3-colored components (the background tile blocks).
    # Keep mixed components containing 9: these are the patterned objects.
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]; seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=3 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==3 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0=min(y for y,x in comp); r1=max(y for y,x in comp); c0=min(x for y,x in comp); c1=max(x for y,x in comp)
            area=(r1-r0+1)*(c1-c0+1)
            if len(comp)==area and area>=25:
                for y,x in comp: out[y][x]=0
    return out
